// restarted dashboard rotates its keys.
var telemetryProxy = &httputil.ReverseProxy{
	Rewrite: func(pr *httputil.ProxyRequest) {
		req := pr.In.Context().Value(telemetryUpstreamKey{}).(telemetryRequest)
		pr.SetURL(req.up.base)

